contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool callerIsAdmin, string calldata description) public payable {
        // Parameterize whether the test contract itself is an admin of c.
        c.isAdmin(address(this));
        bool beforeIsAdmin = c.isAdmin(address(this));

        // The deciding call: must revert exactly when not admin; admin-only entry.
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterIsAdmin = c.isAdmin(address(this));
        // General rule: revert iff this caller is not an admin; admin status is unchanged.
        assert(reverted == !afterIsAdmin && afterIsAdmin == beforeIsAdmin);
    }

    receive() external payable {}
}
